plan_text:
{
  "art_regimen_decision": {
    "decision": "Continue",
    "reason": "Patient's neurological symptoms and elevated carbamazepine level are attributable to carbamazepine toxicity rather than TDF/3TC/DTG, and current creatinine and ALT are acceptable; however, detectable viral load at 1,240 copies/mL requires adherence assessment and repeat viral load per guidelines."
  },
  "problems": [
    {
      "problem": "Carbamazepine toxicity causing neurologic symptoms (headaches, dizziness, ataxia, tremor, nystagmus)",
      "action": "Reduce carbamazepine dose as planned, repeat carbamazepine level, and consider neurology consultation for seizure management on ART.",
      "reason": "Patient has classic carbamazepine toxicity symptoms (nystagmus, ataxia, tremor) with a carbamazepine level of 14, and the guidelines emphasize pharmacovigilance for drug-related toxicity.",
      "clinician_plan_for_this_problem": {
        "decision": "Agree",
        "explanation": "Clinician correctly identified carbamazepine toxicity and plans dose reduction with repeat level, which appropriately addresses the issue."
      }
    },
    {
      "problem": "Detectable viral load (1,240 copies/mL) after prior suppression on TLD",
      "action": "Conduct enhanced adherence counseling, assess for drug interactions, and repeat viral load in 3 months per Uganda HIV guidelines.",
      "reason": "Patient was suppressed (<50 copies/mL) in September 2025 and now has a low-level detectable viral load at 1,240 copies/mL with reported good adherence, warranting adherence support and repeat VL.",
      "clinician_plan_for_this_problem": {
        "decision": "Gap",
        "explanation": "Clinician noted the detectable viral load but expressed uncertainty about the cause and did not outline a clear plan for adherence assessment or repeat viral load."
      }
    },
    {
      "problem": "Potential DTG-carbamazepine drug interaction affecting viral suppression",
      "action": "Review whether carbamazepine may be reducing DTG levels and consider therapeutic drug monitoring or alternative antiepileptic with less interaction potential.",
      "reason": "Carbamazepine is a known inducer that may reduce DTG levels, and the guidelines emphasize pharmacovigilance for drug-drug interactions in patients on ART.",
      "clinician_plan_for_this_problem": {
        "decision": "Not Addressed",
        "explanation": "Clinician did not consider the potential interaction between carbamazepine and DTG as a cause of the detectable viral load."
      }
    },
    {
      "problem": "Mildly elevated ALT (68 U/L) requiring monitoring for hepatotoxicity",
      "action": "Monitor liver function tests at next visit and ensure no worsening trend, as both carbamazepine and ART agents can affect liver function.",
      "reason": "ALT is mildly elevated and the guidelines emphasize pharmacovigilance for drug-related toxicity including hepatotoxicity.",
      "clinician_plan_for_this_problem": {
        "decision": "Not Addressed",
        "explanation": "Clinician did not mention the mildly elevated ALT or plan for follow-up liver function testing."
      }
    }
  ],
  "monitoring_plan": "Repeat carbamazepine level after dose adjustment; repeat viral load in 3 months; monitor ALT and creatinine at next visit; assess adherence and potential drug interactions at follow-up.",
  "patient_counselling": [
    "Explain that carbamazepine dose is being reduced due to toxicity symptoms and that levels will be rechecked.",
    "Counsel on importance of ART adherence and the need to repeat viral load in 3 months.",
    "Advise to report any new or worsening neurologic symptoms, jaundice, or changes in urination.",
    "Discuss potential drug interactions between carbamazepine and DTG with the clinical team."
  ]
}
